True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    templates = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            templates.append(grid[r][start:c])
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            seq = next(s for s in templates if color in s)
            idx = seq.index(color)
            start = c - idx
            for k, value in enumerate(seq):
                x = start + k
                if 0 <= x < w:
                    out[r][x] = value
    return out
